NullPointerException in SubTypeValidator.validateSubType when validating Spring interface #1872New issueCopy linkNew issueCopy linkClosedClosedNullPointerException in SubTypeValidator.validateSubType when validating Spring interface#1872Copy linkMilestone2.8.11.1Descriptionrwinchopened on Jan 5, 2018Issue body actionsIn jackson-databind-2.8.11 jackson-databind-2.9.3 and  jackson-databind-2.9.4-SNAPSHOT SubTypeValidator.validateSubType fails with a NullPointerException if the JavaType.getRawClass() is an interface that starts with org.springframework. For example, the following will fail:
package org.springframework.security.core;

import java.util.*;

public class Authentication {
	private List<GrantedAuthority> authorities = new ArrayList<GrantedAuthority>();

	public List<GrantedAuthority> getAuthorities() {
		return this.authorities;
	}

	public void setAuthorities(List<GrantedAuthority> authorities) {
		this.authorities = authorities;
	}
}
package org.springframework.security.core;

public interface GrantedAuthority {
	String getAuthority();
}
@Test
public void validateSubTypeFailsWithNPE() throws Exception {
	ObjectMapper mapper = new ObjectMapper();
	mapper.enableDefaultTyping(ObjectMapper.DefaultTyping.NON_FINAL, JsonTypeInfo.As.PROPERTY);

	String json = "{\"@class\":\"org.springframework.security.core.Authentication\",\"authorities\":[\"java.util.ArrayList\",[]]}";

	Authentication authentication = mapper.readValue(json, Authentication.class);
}
